import com.github.tomakehurst.wiremock.WireMockServer;
import static com.github.tomakehurst.wiremock.client.WireMock.*;
import static com.github.tomakehurst.wiremock.core.WireMockConfiguration.options;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class PaymentApiClientTest {

    private WireMockServer wireMockServer;

    @BeforeEach
    void setUp() {
        wireMockServer = new WireMockServer(options().dynamicPort());
        wireMockServer.start();
        configureFor("localhost", wireMockServer.port());
    }

    @AfterEach
    void tearDown() {
        wireMockServer.stop();
    }

    @Test
    void shouldHandleSuccessfulPaymentResponse() {
        stubFor(post(urlEqualTo("/api/v1/payments"))
            .withHeader("Authorization", equalTo("Bearer secret-token"))
            .withRequestBody(matchingJsonPath("$.amount", greaterThan(0)))
            .willReturn(aResponse()
                .withStatus(200)
                .withHeader("Content-Type", "application/json")
                .withBody("{\"status\": \"SUCCESS\", \"transactionId\": \"tx_12345\"}")));

        // Execute application client code pointing to wireMockServer.baseUrl()
    }
}
